password = "password123"

letters = digits = symbols = 0
for ch in password:
    if ch.isalpha():
        letters += 1
    elif ch.isdigit():
        digits += 1
    else:
        symbols += 1

# Har shart (condition) poori hone par 1 point: lambai 8+, letters, numbers, symbols
score = sum([len(password) >= 8, letters > 0, digits > 0, symbols > 0])
if password.lower() in ["password", "password123", "123456", "12345678", "qwerty"]:
    score = 0                     # bohat aam password, foran guess ho jata hai

print("Letters:", letters, "| Numbers:", digits, "| Symbols:", symbols, "| Lambai:", len(password))
if score == 4:
    print("Mazboot (strong) password")
elif score == 3:
    print("Theek hai, magar aur mazboot ho sakta hai")
else:
    print("Kamzor (weak) password")
